function TwoFactorSection() {
  const { language } = useLanguage();
  const { user } = useLocalAuth();
  const ar = language === 'ar';
  // Every 2FA call is keyed by the authenticated user id. A literal placeholder
  // here would enrol the secret against a non-existent account, so the user
  // would set it up, scan the QR code, and then be silently locked out.
  const userId = user?.id ?? '';
  const available = isTwoFactorAvailable();
  const [setup, setSetup] = useState<TwoFactorSetup | null>(null);
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [enabled, setEnabled] = useState(false);
  const [verifying, setVerifying] = useState(false);

  const unavailableReason = !available
    ? (ar ? 'التحقق الثنائي غير متاح في هاي البيئة.' : 'Two-factor authentication is not available in this environment.')
    : !userId
      ? (ar ? 'سجّل الدخول لإدارة التحقق الثنائي لحسابك.' : 'Sign in to manage two-factor authentication for your account.')
      : null;

  const handleSetup = useCallback(async () => {
    setError(null);
    if (!userId || !available) {
      return;
    }
    setLoading(true);
    try {
      const result = await enable2FA(userId);
      setSetup(result);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to set up 2FA.';
      // The server refuses to restart setup while 2FA is on, so show the disable control.
      if (/already enabled/i.test(message)) {
        setEnabled(true);
      }
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [available, userId]);

  const handleVerify = useCallback(async () => {
    setError(null);
    if (!userId) {
      return;
    }
    if (!code.trim() || code.length < 6) {
      setError('Enter the 6-digit verification code.');
      return;
    }
    setVerifying(true);
    try {
      const valid = await verify2FACode(userId, code);
      if (valid) {
        setEnabled(true);
        setSetup(null);
        setCode('');
      } else {
        setError('Invalid verification code. Please try again.');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Verification failed.');
    } finally {
      setVerifying(false);
    }
  }, [code, userId]);

  const handleDisable = useCallback(async () => {
    setError(null);
    if (!userId) {
      return;
    }
    if (!code.trim() || code.length < 6) {
      setError('Enter the 6-digit verification code to disable 2FA.');
      return;
    }
    setVerifying(true);
    try {
      const disabled = await disable2FA(userId, code);
      if (disabled) {
        setEnabled(false);
        setCode('');
      } else {
        setError('Failed to disable 2FA. Please try again.');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Disabling 2FA failed.');
    } finally {
      setVerifying(false);
    }
  }, [code, userId]);

  const handleCopyBackupCodes = useCallback(() => {
    if (setup?.backupCodes) {
      void navigator.clipboard.writeText(setup.backupCodes.join('\n'));
    }
  }, [setup]);

  return (
    <SectionCard
      title={ar ? 'التحقق الثنائي' : 'Two-Factor Authentication'}
      subtitle={
        ar
          ? 'فعّل التحقق الثنائي لحماية حسابك بطبقة أمان إضافية.'
          : 'Enable two-factor authentication to add an extra layer of security to your account.'
      }
      icon={<KeyRound size={18} color={C.gold} />}
    >
      <div style={{ display: 'grid', gap: 12 }}>
        {unavailableReason ? (
          <div
            role="status"
            style={{ color: 'var(--muted-foreground)', fontSize: TYPE.size.sm, padding: SPACE[3], background: 'var(--secondary)', borderRadius: R.lg }}
          >
            {unavailableReason}
          </div>
        ) : null}

        {error ? (
          <div style={{ color: 'var(--destructive)', fontSize: TYPE.size.sm, padding: SPACE[3], background: `${'var(--destructive)'}15`, borderRadius: R.lg }}>
            {error}
          </div>
        ) : null}

        {!enabled && !setup ? (
          <div style={{ display: 'flex', gap: SPACE[3], flexWrap: 'wrap' }}>
            <WaselButton
              type="button"
              variant="primary"
              onClick={() => { void handleSetup(); }}
              loading={loading}
              disabled={loading || Boolean(unavailableReason)}
              icon={<Smartphone size={16} />}
            >
              {ar ? 'فعّل التحقق الثنائي' : 'Enable 2FA'}
            </WaselButton>
          </div>
        ) : null}

        {setup ? (
          <div style={{ display: 'grid', gap: SPACE[4], padding: SPACE[4], background: 'var(--secondary)', borderRadius: R.xl, border: `1px solid ${'var(--border)'}` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: SPACE[3] }}>
              <QrCode size={24} color={'var(--primary)'} />
              <div>
                <div style={{ color: 'var(--foreground)', fontWeight: TYPE.weight.black, fontSize: TYPE.size.sm }}>
                  {ar ? 'مسح رمز QR' : 'Scan QR Code'}
                </div>
                <div style={{ color: 'var(--muted-foreground)', fontSize: TYPE.size.xs }}>
                  {ar ? 'استخدم تطبيق المصادقة لمسح الرمز' : 'Use an authenticator app to scan the code'}
                </div>
              </div>
            </div>

            {setup.qrCode ? (
              <img
                src={setup.qrCode}
                alt={ar ? 'رمز QR لإعداد تطبيق المصادقة' : 'QR code for your authenticator app'}
                width={192}
                height={192}
                style={{ justifySelf: 'center', background: '#fff', padding: SPACE[2], borderRadius: R.lg }}
              />
            ) : null}

            {setup.secret ? (
              <div style={{ display: 'grid', gap: 6 }}>
                <div style={{ color: 'var(--muted-foreground)', fontSize: TYPE.size.xs }}>
                  {ar
                    ? 'أو أدخل هاد المفتاح يدوياً في تطبيق المصادقة:'
                    : 'Or enter this key manually in your authenticator app:'}
                </div>
                <code
                  dir="ltr"
                  style={{
                    background: 'var(--background)',
                    borderRadius: R.md,
                    padding: `${SPACE[2]} ${SPACE[3]}`,
                    fontFamily: 'monospace',
                    fontSize: TYPE.size.sm,
                    color: 'var(--foreground)',
                    overflowWrap: 'anywhere',
                    userSelect: 'all',
                  }}
                >
                  {setup.secret}
                </code>
              </div>
            ) : null}

            {setup.secret ? (
              <div style={{ display: 'flex', gap: SPACE[2], alignItems: 'center' }}>
                <WaselInput
                  value={code}
                  onChange={value => setCode(value)}
                  placeholder={ar ? 'أدخل الرمز' : 'Enter verification code'}
                  maxLength={6}
                  style={{ flex: 1 }}
                />
                <WaselButton
                  type="button"
                  variant="primary"
                  onClick={() => { void handleVerify(); }}
                  loading={verifying}
                  disabled={verifying}
                >
                  {ar ? 'تحقق' : 'Verify'}
                </WaselButton>
              </div>
            ) : null}

            {setup.backupCodes && setup.backupCodes.length > 0 ? (
              <div>
                <div style={{ color: 'var(--muted-foreground)', fontSize: TYPE.size.xs, marginBottom: SPACE[2] }}>
                  {ar ? 'أكواد الاحتياطية (احفظها في مكان آمن):' : 'Backup codes (save these in a safe place):'}
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: SPACE[2] }}>
                  {setup.backupCodes.map((bc, i) => (
                    <div key={i} style={{ background: 'var(--background)', borderRadius: R.md, padding: `${SPACE[2]} ${SPACE[3]}`, fontFamily: 'monospace', fontSize: TYPE.size.sm, color: 'var(--foreground)', textAlign: 'center' }}>
                      {bc}
                    </div>
                  ))}
                </div>
                <WaselButton
                  type="button"
                  variant="outline"
                  onClick={() => { void handleCopyBackupCodes(); }}
                  style={{ marginTop: SPACE[3], background: 'var(--secondary)', color: 'var(--foreground)' }}
                  icon={<RefreshCw size={14} />}
                >
                  {ar ? 'انسخ الأكواد' : 'Copy codes'}
                </WaselButton>
              </div>
            ) : null}
          </div>
        ) : null}

        {enabled ? (
          <div style={{ padding: SPACE[4], background: `${C.green}15`, borderRadius: R.xl, border: `1px solid ${C.green}40` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: SPACE[3], marginBottom: SPACE[3] }}>
              <ShieldCheck size={20} color={C.green} />
              <span style={{ color: C.green, fontWeight: TYPE.weight.black, fontSize: TYPE.size.sm }}>
                {ar ? 'التحقق الثنائي مفعّل' : '2FA is enabled'}
              </span>
            </div>
            <div style={{ display: 'flex', gap: SPACE[3], flexWrap: 'wrap' }}>
              <WaselInput
                value={code}
                onChange={value => setCode(value)}
                placeholder={ar ? 'أدخل الرمز لتعطيل' : 'Enter code to disable'}
                maxLength={6}
                style={{ flex: 1 }}
              />
              <WaselButton
                type="button"
                variant="outline"
                onClick={() => { void handleDisable(); }}
                loading={verifying}
                disabled={verifying}
                style={{ background: `${'var(--destructive)'}15`, borderColor: `${'var(--destructive)'}40`, color: 'var(--destructive)' }}
              >
                {ar ? 'عطّل' : 'Disable'}
              </WaselButton>
            </div>
          </div>
        ) : null}
      </div>
    </SectionCard>
  );
}

